// 1) Convertimos las 6 filas de Airtable en un objeto plano
// Airtable puede devolver los campos en la raíz o anidados bajo "fields",
// según la versión del nodo. Contemplamos las dos formas.
const config = {};
for (const item of $input.all()) {
  const f = item.json.fields ?? item.json;
  if (f.Clave) config[f.Clave] = f.Valor;
}

if (Object.keys(config).length === 0) {
  throw new Error('La tabla Config y Prompts no devolvio filas. Revisa el nodo [4].');
}

// 2) Recuperamos los datos del lead, que quedaron dos nodos atrás
const lead = $('[2] Normalizar Datos de Entrada').first().json;

// 3) Normalizamos la industria contra el catálogo del Single select
const INDUSTRIAS = ['Manufactura','Tecnologia y Software','Servicios Profesionales',
  'Retail y E-commerce','Salud','Educacion','Logistica y Transporte',
  'Construccion','Agro','Finanzas y Seguros','Otra'];

const sinTildes = (s) => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const entrada = sinTildes(lead.industria);

const industriaNormalizada = INDUSTRIAS.find(op => sinTildes(op) === entrada)
  || INDUSTRIAS.find(op => sinTildes(op).includes(entrada) && entrada.length > 3)
  || 'Otra';

// 4) Devolvemos todo junto en un solo ítem
return [{
  json: {
    ...lead,
    industria: industriaNormalizada,
    config
  }
}];

// --- 0) Traer datos de nodos anteriores, tolerando variaciones en el nombre ---
function traerNodo(...nombres) {
  for (const n of nombres) {
    try {
      const r = $(n).first();
      if (r) return r.json;
    } catch (e) {}
  }
  throw new Error('No encontre ninguno de estos nodos: ' + nombres.join(' | '));
}

const previo   = traerNodo('[4b] Mapear Config a Variables');
const registro = traerNodo('[6] Crear Registro de Lead');
const raw = $input.first().json;

// --- 1) Extraer el texto ---
// Anthropic devuelve "content" como ARRAY de bloques, no como string
let texto = '';
if (Array.isArray(raw.content)) {
  texto = raw.content.map(b => b.text || '').join('');
} else {
  texto = raw.content ?? raw.text ?? raw.message?.content ?? '';
}
if (typeof texto === 'object') texto = JSON.stringify(texto);

// --- 2) Limpieza defensiva ---
texto = texto.replace(/```json/gi, '').replace(/```/g, '').trim();
if (texto && !texto.startsWith('{')) texto = '{' + texto;  // por si usaste prefill

// --- 3) Parseo con red de contención ---
let clasificacion;
try {
  clasificacion = JSON.parse(texto);
} catch (e) {
  // Si la IA devolvió basura, NO rompemos: degradamos a un valor seguro
  clasificacion = {
    score: 0,
    categoria: 'Descartado',
    urgencia: 'Baja',
    justificacion: 'ERROR_PARSEO: la IA devolvio un formato invalido',
    necesidad_detectada: 'N/D',
    _error_parseo: true
  };
}

// --- 4) Validación de rangos y tipos ---
const score = Number(clasificacion.score);
clasificacion.score = (Number.isFinite(score) && score >= 0 && score <= 100) ? score : 0;

const categoriasValidas = ['VIP', 'Estandar', 'Descartado'];
if (!categoriasValidas.includes(clasificacion.categoria)) {
  clasificacion.categoria = 'Estandar';
}

return [{
  json: {
    ...previo,
    clasificacion,
    recordId: registro.id,
    tokensInput: raw.usage?.input_tokens ?? 0,
    tokensOutput: raw.usage?.output_tokens ?? 0,
    tokensCacheados: raw.usage?.cache_read_input_tokens ?? 0
  }
}];

