function traerNodo(...nombres) {
  for (const n of nombres) {
    try { const r = $(n).first(); if (r) return r.json; } catch (e) {}
  }
  throw new Error('No encontre ninguno de estos nodos: ' + nombres.join(' | '));
}

const previo = traerNodo('[8] Parsear Respuesta de Clasificacion');
const raw = $input.first().json;

// Extraer el texto (content es un array de bloques en Anthropic)
let texto = '';
if (Array.isArray(raw.content)) {
  texto = raw.content.map(b => b.text || '').join('');
} else {
  texto = raw.content ?? raw.text ?? '';
}
texto = texto.replace(/```json/gi, '').replace(/```/g, '').trim();

// Parseo con red de contención: si falla, NO perdemos el trabajo del modelo
let propuesta;
try {
  propuesta = JSON.parse(texto);
} catch (e) {
  propuesta = {
    asunto: 'Propuesta comercial',
    cuerpo: texto || 'ERROR: la IA no devolvio contenido',
    _error_parseo: true
  };
}

if (!propuesta.asunto) propuesta.asunto = 'Propuesta comercial';
if (!propuesta.cuerpo) propuesta.cuerpo = texto;

// Sumamos el costo de la redaccion (Sonnet: $3 input / $15 output por millon)
const inSonnet  = raw.usage?.input_tokens  ?? 0;
const outSonnet = raw.usage?.output_tokens ?? 0;
const costoSonnet = (inSonnet * 3 + outSonnet * 15) / 1000000;
const costoHaiku  = (previo.tokensInput * 1 + previo.tokensOutput * 5) / 1000000;

return [{
  json: {
    ...previo,
    asunto: propuesta.asunto,
    cuerpo: propuesta.cuerpo,
    costoTotal: costoHaiku + costoSonnet,
    tokensInputSonnet: inSonnet,
    tokensOutputSonnet: outSonnet
  }
}];

